40	/**
41	 * Class for performing on demand scans of containers.
42	 */
43	public final class OnDemandContainerDataScanner {
44	  public static final Logger LOG =
45	      LoggerFactory.getLogger(OnDemandContainerDataScanner.class);
46	
47	  private final ExecutorService scanExecutor;
48	  private final ContainerController containerController;
49	  private final DataTransferThrottler throttler;
50	  private final Canceler canceler;
51	  private final ConcurrentHashMap
52	      .KeySetView<Long, Boolean> containerRescheduleCheckSet;
53	  private final OnDemandScannerMetrics metrics;
54	  private final long minScanGap;
55	
56	  public OnDemandContainerDataScanner(
57	      ContainerScannerConfiguration conf, ContainerController controller) {
58	    containerController = controller;
59	    throttler = new DataTransferThrottler(
60	        conf.getOnDemandBandwidthPerVolume());
61	    canceler = new Canceler();
62	    metrics = OnDemandScannerMetrics.create();
63	    scanExecutor = Executors.newSingleThreadExecutor();
64	    containerRescheduleCheckSet = ConcurrentHashMap.newKeySet();
65	    minScanGap = conf.getContainerScanMinGap();
66	  }
67	
68	  private boolean shouldScan(Container<?> container) {
69	    if (container == null) {
70	      return false;
71	    }
72	    long containerID = container.getContainerData().getContainerID();
73	
74	    HddsVolume containerVolume = container.getContainerData().getVolume();
75	    if (containerVolume.isFailed()) {
76	      LOG.debug("Skipping on demand scan for container {} since its volume {}" +
77	          " has failed.", containerID, containerVolume);
78	      return false;
79	    }
80	
81	    return !ContainerUtils.recentlyScanned(container, minScanGap,
82	        LOG) && container.shouldScanData();
83	  }
84	
85	  public Optional<Future<?>> scanContainer(Container<?> container) {
86	    if (!shouldScan(container)) {
87	      return Optional.empty();
88	    }
89	
90	    Future<?> resultFuture = null;
91	    long containerId = container.getContainerData().getContainerID();
92	    if (addContainerToScheduledContainers(containerId)) {
93	      resultFuture = scanExecutor.submit(() -> {
94	        performOnDemandScan(container);
95	        removeContainerFromScheduledContainers(containerId);
96	      });
97	    }
98	    return Optional.ofNullable(resultFuture);
99	  }
100	
101	  private boolean addContainerToScheduledContainers(long containerId) {
102	    return containerRescheduleCheckSet.add(containerId);
103	  }
104	
105	  private void removeContainerFromScheduledContainers(
106	      long containerId) {
107	    containerRescheduleCheckSet.remove(containerId);
108	  }
109	
110	  private void performOnDemandScan(Container<?> container) {
111	    if (!shouldScan(container)) {
112	      return;
113	    }
114	
115	    long containerId = container.getContainerData().getContainerID();
116	    try {
117	      ContainerData containerData = container.getContainerData();
118	      logScanStart(containerData);
119	
120	      ScanResult result = container.scanData(throttler, canceler);
121	      // Metrics for skipped containers should not be updated.
122	      if (result.isDeleted()) {
123	        LOG.debug("Container [{}] has been deleted during the data scan.", containerId);
124	      } else {
125	        if (!result.isHealthy()) {
126	          logUnhealthyScanResult(containerId, result, LOG);
127	          boolean containerMarkedUnhealthy = containerController
128	              .markContainerUnhealthy(containerId, result);
129	          if (containerMarkedUnhealthy) {
130	            metrics.incNumUnHealthyContainers();
131	          }
132	        }
133	        // TODO HDDS-10374 will need to update the merkle tree here as well.
134	        metrics.incNumContainersScanned();
135	      }
136	
137	      // Even if the container was deleted, mark the scan as completed since we already logged it as starting.
138	      Instant now = Instant.now();
139	      logScanCompleted(containerData, now);
140	
141	      if (!result.isDeleted()) {
142	        containerController.updateDataScanTimestamp(containerId, now);
143	      }
144	    } catch (IOException e) {
145	      LOG.warn("Unexpected exception while scanning container "
146	          + containerId, e);
147	    } catch (InterruptedException ex) {
148	      // This should only happen as part of shutdown, which will stop the
149	      // ExecutorService.
150	      LOG.info("On demand container scan interrupted.");
151	    }
152	  }
153	
154	  private void logScanStart(ContainerData containerData) {
155	    if (LOG.isDebugEnabled()) {
